/**
 * Mock the eventsProcessor#getConfigValueFromMetastore method and make it return
 * incorrect values for the required configs for event processing. Verify that the
 * incorrect config leads to invalid result for each config.
 */
@Test
public void testConfigValidationWithIncorrectValues() throws TException {
    MetastoreEventsProcessor mockEventsProcessor = Mockito.mock(MetastoreEventsProcessor.class);
    for (TestIncorrectMetastoreEventConfigs config : TestIncorrectMetastoreEventConfigs.values()) {
        when(mockEventsProcessor.getConfigValueFromMetastore(config.conf_, DEFAULT_METASTORE_CONFIG_VALUE)).thenReturn(config.incorrectValue_);
        ValidationResult testResult = validateMetastoreConfigs(mockEventsProcessor);
        assertFalse(testResult.isValid());
        assertTrue(testResult.getReason().isPresent());
        assertEquals(String.format("Incorrect configuration for %s. " + "Found : %s", config.toString(), config.incorrectValue_), testResult.getReason().get());
        when(mockEventsProcessor.getConfigValueFromMetastore(config.conf_, DEFAULT_METASTORE_CONFIG_VALUE)).thenReturn(config.correctValue_);
    }
}

/**
 * Test that when HiveConf.METASTORE_PARAMETER_EXCLUDE_PATTERNS contains a regex
 * that filters out any parameter required for event processing, the config
 * validation fails. Config validation should succeed when the regex does not match
 * any of the required parameters.
 */
@Test
public void testParameterFilterValidation() throws TException {
    MetastoreEventsProcessor mockEventsProcessor = Mockito.mock(MetastoreEventsProcessor.class);
    //Regex to filter all parameters starting with impala
    when(mockEventsProcessor.getConfigValueFromMetastore(METASTORE_PARAMETER_EXCLUDE_PATTERNS, DEFAULT_METASTORE_CONFIG_VALUE)).thenReturn("^impala");
    ValidationResult testResult = validateMetastoreEventParameters(mockEventsProcessor);
    assertFalse(testResult.isValid());
    assertTrue(testResult.getReason().isPresent());
    when(mockEventsProcessor.getConfigValueFromMetastore(METASTORE_PARAMETER_EXCLUDE_PATTERNS, DEFAULT_METASTORE_CONFIG_VALUE)).thenReturn("impala*");
    testResult = validateMetastoreEventParameters(mockEventsProcessor);
    assertFalse(testResult.isValid());
    assertTrue(testResult.getReason().isPresent());
    when(mockEventsProcessor.getConfigValueFromMetastore(METASTORE_PARAMETER_EXCLUDE_PATTERNS, DEFAULT_METASTORE_CONFIG_VALUE)).thenReturn("");
    testResult = validateMetastoreEventParameters(mockEventsProcessor);
    assertTrue(testResult.isValid());
    assertFalse(testResult.getReason().isPresent());
    // Test with default return value
    when(mockEventsProcessor.getConfigValueFromMetastore(METASTORE_PARAMETER_EXCLUDE_PATTERNS, DEFAULT_METASTORE_CONFIG_VALUE)).thenReturn(DEFAULT_METASTORE_CONFIG_VALUE);
    testResult = validateMetastoreEventParameters(mockEventsProcessor);
    assertTrue(testResult.isValid());
    assertFalse(testResult.getReason().isPresent());
    when(mockEventsProcessor.getConfigValueFromMetastore(METASTORE_PARAMETER_EXCLUDE_PATTERNS, DEFAULT_METASTORE_CONFIG_VALUE)).thenReturn("randomString1, impala" + ".disableHmsSync, randomString2");
    testResult = validateMetastoreEventParameters(mockEventsProcessor);
    assertFalse(testResult.isValid());
    assertTrue(testResult.getReason().isPresent());
    //Test when a required parameter is given as regex
    String requiredParameter = MetastoreEventPropertyKey.CATALOG_SERVICE_ID.getKey();
    when(mockEventsProcessor.getConfigValueFromMetastore(METASTORE_PARAMETER_EXCLUDE_PATTERNS, DEFAULT_METASTORE_CONFIG_VALUE)).thenReturn(requiredParameter);
    testResult = validateMetastoreEventParameters(mockEventsProcessor);
    assertFalse(testResult.isValid());
    assertTrue(testResult.getReason().isPresent());
    // Verify that the error message is correct
    assertEquals(String.format("Failed config validation. " + "Required Impala parameter %s is" + " filtered out using the Hive configuration %s=%s", requiredParameter, METASTORE_PARAMETER_EXCLUDE_PATTERNS, requiredParameter), testResult.getReason().get());
    when(mockEventsProcessor.getConfigValueFromMetastore(METASTORE_PARAMETER_EXCLUDE_PATTERNS, DEFAULT_METASTORE_CONFIG_VALUE)).thenReturn("^impala.events" + ".catalogServiceId");
    testResult = validateMetastoreEventParameters(mockEventsProcessor);
    assertFalse(testResult.isValid());
    assertTrue(testResult.getReason().isPresent());
}

